function Hub({ go, mode }: { go: (s: Screen) => void; mode: Mode }) {
  return <Shell go={go} mode={mode}><header className="flex h-[72px] items-center justify-between border-b border-border/70 px-5 lg:px-9"><div className="flex items-center gap-3 md:hidden"><Logo compact /><span className="text-sm font-semibold">Projects</span></div><div className="hidden items-center gap-2 text-sm text-muted-foreground md:flex"><LayoutDashboard size={16} className="text-primary" /> All projects <span className="text-border">/</span> <span className="text-foreground">Overview</span></div><div className="flex items-center gap-2"><button className="grid size-9 place-items-center rounded-lg border border-border text-muted-foreground hover:bg-secondary" data-testid="button-search"><Search size={16} /></button><Button onClick={() => go("launchpad")} className="hidden px-3.5 py-2 sm:inline-flex" testId="button-new-project"><Plus size={15} /> New project</Button></div></header><main className="mx-auto max-w-[1220px] px-5 py-9 lg:px-9"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="font-mono text-[10px] uppercase tracking-[.22em] text-primary">Your command center</div><h1 className="mt-3 font-display text-4xl font-semibold tracking-[-.055em]">Good morning, Alex<span className="text-primary">.</span></h1><p className="mt-2 text-sm text-muted-foreground">Three environments are keeping your ideas moving.</p></div><div className="flex items-center gap-2"><Pill tone="teal"><span className="size-1.5 rounded-full bg-primary" /> All systems operational</Pill></div></div><div className="mt-10 grid gap-4 lg:grid-cols-[1.28fr_.72fr]"><button onClick={() => go("launchpad")} className="group relative min-h-[190px] overflow-hidden rounded-2xl border border-primary/30 bg-primary/8 p-7 text-left transition-all hover:border-primary/60 hover:bg-primary/10" data-testid="card-new-project"><div className="absolute -right-12 -top-24 size-72 rounded-full border border-primary/10 bg-primary/10 blur-2xl transition-transform group-hover:scale-110" /><div className="relative flex h-full flex-col justify-between"><div><div className="flex items-center gap-2 text-primary"><Plus size={17} /><span className="font-mono text-[10px] uppercase tracking-[.2em]">Launchpad</span></div><h2 className="mt-8 font-display text-3xl font-semibold tracking-tight">Start a new project</h2><p className="mt-2 text-sm text-muted-foreground">Prompt an app into existence or bring an existing repo.</p></div><div className="flex items-center gap-2 text-xs font-semibold text-primary">Open launchpad <ArrowRight size={14} /></div></div></button><div className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Workspace pulse</span><Activity size={16} className="text-primary" /></div><div className="mt-7 flex items-end gap-3"><span className="font-display text-4xl font-semibold">08</span><span className="mb-1 text-xs text-muted-foreground">agent runs this week</span></div><div className="mt-5 flex h-9 items-end gap-1.5">{[18, 25, 20, 32, 27, 38, 35, 45, 40, 53, 48, 65, 58, 74].map((h, i) => <div key={i} className={`flex-1 rounded-t-sm ${i > 9 ? "bg-primary" : "bg-primary/25"}`} style={{ height: `${h}%` }} />)}</div><div className="mt-3 flex justify-between font-mono text-[9px] text-muted-foreground"><span>MAR 04</span><span>MAR 10</span></div></div></div><div className="mt-12 flex items-center justify-between"><div><h2 className="font-display text-2xl font-semibold tracking-tight">Active environments</h2><p className="mt-1 text-xs text-muted-foreground">Your living projects, in one place.</p></div><button className="flex items-center gap-1 text-xs font-semibold text-muted-foreground hover:text-primary" data-testid="button-view-all">View archive <ArrowRight size={13} /></button></div><div className="mt-5 grid gap-3">{projects.map((p, i) => <button key={p.name} onClick={() => go("workspace")} className="group flex flex-col gap-5 rounded-xl border border-border bg-card p-5 text-left transition-all hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-lg sm:flex-row sm:items-center" data-testid={`card-project-${i}`}><div className={`grid size-11 shrink-0 place-items-center rounded-xl ${p.color === "teal" ? "bg-primary/15 text-primary" : p.color === "amber" ? "bg-accent/15 text-accent" : "bg-violet-300/15 text-violet-200"}`}><Box size={20} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-3"><h3 className="font-display text-lg font-semibold">{p.name}</h3>{p.live && <Pill tone="teal"><span className="size-1.5 rounded-full bg-primary pulse-dot" /> Live</Pill>}</div><p className="mt-1 text-sm text-muted-foreground">{p.desc}</p><p className="mt-2 font-mono text-[10px] text-muted-foreground/70">{p.time}</p></div><div className="flex items-center gap-2">{p.prd && <Pill>PRD Generated</Pill>}{p.synced && <Pill tone="violet">Synced</Pill>}<ChevronRight size={18} className="ml-2 text-muted-foreground transition-transform group-hover:translate-x-1 group-hover:text-primary" /></div></button>)}</div></main></Shell>;
}

